            ->select('c')
            ->from(EagerFetchChild::class, 'c')
            ->join('c.owner', 'o')
            ->where('o.id = :id')
            ->setParameter('id', 1)
            ->setFetchMode(EagerFetchChild::class, 'owner', ClassMetadata::FETCH_LAZY);

